select.where:
n.del_flag = '0'

    and n.notice_type = #{noticeType}


    and n.scope_type = #{scopeType}


    and n.competition_series_id = #{competitionSeriesId}


    and exists (
        select 1 from competition_scene_notice_schedule fns
        where fns.notice_id = n.notice_id and fns.schedule_id = #{scheduleId}
    )


    and n.target_id = #{targetId}


    and n.title like concat('%', #{title}, '%')


    and n.notice_level = #{noticeLevel}


    and n.publish_status = #{publishStatus}

mapper.select:

where n.del_flag = '0'
  and n.status = '0'
  and n.publish_status = 'PUBLISHED'
  and (n.publish_time is null or n.publish_time <= now())
  and (n.expire_time is null or n.expire_time > now())
  and (
      (
          n.notice_type = 'PERSONAL'
          and n.scope_type = 'PERSON'
          and (
              n.user_id = #{userId}

                  or n.member_id in

                      #{memberId}



                  or n.target_id in

                      #{targetId}


          )
      )

          or (
              n.notice_type = 'ANNOUNCEMENT'
              and n.scope_type = 'COMPETITION'
              and n.competition_series_id in

                  #{seriesId}

          )


          or (
              n.notice_type = 'ANNOUNCEMENT'
              and n.scope_type = 'SCHEDULE'
              and n.competition_series_id in

                  #{seriesId}

              and exists (
                  select 1
                  from competition_scene_notice_schedule ns
                  where ns.notice_id = n.notice_id
                    and ns.schedule_id in

                        #{scheduleId}

              )
          )

  )
